import '../value_objects/order_status.dart';

/// Result of successfully submitting an `Order` draft through `submitOrder`
/// (EPIC-13, TASK-101) — every field here is exactly what the Cloud Function
/// returned, never recomputed or guessed client-side (same "pricing
/// definitivo server-side" precedent every other server-authoritative result
/// in this codebase already follows, e.g. `OrderPricingSummary`).
///
/// [orderNumber] is the one and only unique order number: generated by the
/// Cloud Function's own transactional per-company sequence, never by the
/// client. A resubmission of the very same draft (double tap, retry after a
/// dropped response) always resolves to the exact same [orderId]/
/// [orderNumber] — `submitOrder`'s idempotency contract.
final class OrderSubmissionResult {
  const OrderSubmissionResult({
    required this.orderId,
    required this.orderNumber,
    required this.status,
    required this.discountAmount,
    required this.surchargeAmount,
    required this.shippingAmount,
    required this.total,
    required this.submittedAt,
  });

  final String orderId;
  final String orderNumber;
  final OrderStatus status;
  final double discountAmount;
  final double surchargeAmount;
  final double shippingAmount;
  final double total;
  final DateTime submittedAt;
}
